/* engines/mediaelement.js — part of the universal player. Generated by the one-off split;
 * every top-level name lives on the shared context P (see context.js). */
import { P } from "../context.js";

export function install(P) {


  /* MediaElement.js wraps the shared element once and then delegates play,
     pause and seeking to its native HTML5 renderer. Its own control bar is
     mounted in the player's seek row — the same place WaveSurfer uses. */
  async function createMediaElement(url, startAt, autoplay) {
    try { await P.loadMediaElementScript(); } catch {
      P.fallbackToHtml5();
      P.notify("engine");
      return false;
    }
    if (!window.MediaElement) {
      P.fallbackToHtml5();
      P.notify("engine");
      return false;
    }

    P.showEngineUi("mediaelement");
    P.audio.src = url;
    P.audio.load();
    if (!P.mediaElementWrapper) {
      try {
        // MediaElementPlayer builds the recognizable control bar; the plain
        // MediaElement core would only wrap the element without any UI.
        const PlayerClass = window.MediaElementPlayer || window.MediaElement;
        P.mediaElementWrapper = new PlayerClass(P.audio, {
          features: ["playpause", "current", "progress", "duration", "volume"],
        });
      } catch {
        P.mediaElementWrapper = null;
      }
    }
    if (!P.mediaElementWrapper) {
      P.fallbackToHtml5();
      P.notify("engine");
      return false;
    }
    const host = P.$("labMediaElement");
    const container = P.mediaElementWrapper.container
      || (P.audio.parentElement && P.audio.parentElement !== P.bar ? P.audio.parentElement : null);
    if (host && container && host.firstElementChild !== container) host.replaceChildren(container);
    if (startAt) P.setTime(startAt);
    if (autoplay) P.attemptPlay();
    return true;
  }
  Object.assign(P, { createMediaElement });
}
